import { useState, useCallback } from 'react';
import { Button, Drawer, Menu, MenuItem, Divider } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface NavDrawerProps {
  onNavigate: (key: NavKey) => void;
}

const ITEMS: { key: NavKey; label: string }[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function NavDrawer({ onNavigate }: NavDrawerProps) {
  const [open, setOpen] = useState(false);

  const select = useCallback(
    (key: NavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate]
  );

  return (
    <>
      <Button onClick={() => setOpen(true)} aria-haspopup="menu" aria-expanded={open}>
        Меню
      </Button>

      <Drawer
        open={open}
        placement="left"
        onClose={() => setOpen(false)}
        aria-label="Навигация"
      >
        <Menu style={{ padding: 'var(--jx-space-2)' }}>
          {ITEMS.map((item) => (
            <MenuItem key={item.key} onSelect={() => select(item.key)}>
              {item.label}
            </MenuItem>
          ))}

          <Divider style={{ margin: 'var(--jx-space-2) 0' }} />

          <MenuItem tone="danger" onSelect={() => select('logout')}>
            Выйти
          </MenuItem>
        </Menu>
      </Drawer>
    </>
  );
}

